export async function mountEcologyCapture({getUser,isAdmin,compress,store,renderDrafts}){
 const section=document.querySelector('#ecology-capture');
 try{const response=await fetch('./campus-ecology.json');if(!response.ok)throw Error('生態主題載入失敗');const data=await response.json();section.innerHTML='<h2>生態景點定位與拍照</h2><p><a href="./index.html?topic=ecology&amp;edit=1">拖曳調整景點位置 ↗</a></p><p>站在同一安全位置，以第一張照片的朝向為前方，拍前、右、後、左四張水平照片。一般照片不會自動變成3D模型；完整環景須是2:1球面原圖。</p><label>生態景點<select id="eco-target"></select></label><label>照片類型<select id="eco-kind"></select></label><p><a id="eco-tour">查看這個景點的四向導覽 ↗</a></p><label><input id="eco-confirm" type="checkbox"> 我已確認景點與方向，照片可公開</label><label>照片說明<textarea id="eco-description" maxlength="1000" placeholder="記錄現場環境，避免拍到可辨識的學生"></textarea></label><label>開啟相機<input id="eco-camera" type="file" accept="image/*" capture="environment" disabled></label><label>或選擇相簿照片<input id="eco-album" type="file" accept="image/*" disabled></label><p id="eco-photo-status" role="status"></p>';
 const $=s=>section.querySelector(s),kinds=[['north','前方'],['east','右方'],['south','後方'],['west','左方'],['entrance','入口／環境全景'],['path','步道／生態細節'],['panorama','完整360°球面環景（2:1）']];let busy=false;
 for(const row of data.rows){const o=document.createElement('option');o.value=row.id;o.textContent=row.id+' '+row.title;$('#eco-target').append(o)}for(const [value,label]of kinds){const o=document.createElement('option');o.value=value;o.textContent=label;$('#eco-kind').append(o)}
 const requested=new URLSearchParams(location.search).get('eco');if(data.rows.some(r=>r.id===requested))$('#eco-target').value=requested;
 function update(){const enabled=isAdmin()&&$('#eco-confirm').checked&&!busy;$('#eco-camera').disabled=$('#eco-album').disabled=!enabled;$('#eco-tour').href='./tour.html?mode=simple&station='+$('#eco-target').value}
 $('#eco-target').onchange=()=>{$('#eco-confirm').checked=false;update()};$('#eco-kind').onchange=update;$('#eco-confirm').onchange=update;document.addEventListener('teacher-context-change',()=>{$('#eco-confirm').checked=false;update()});
 async function capture(file){if(!file||!isAdmin()||!$('#eco-confirm').checked||busy)return;busy=true;update();const owner=getUser().uid,target=$('#eco-target').value,kind=$('#eco-kind').value,title=data.rows.find(r=>r.id===target).title+' '+kinds.find(k=>k[0]===kind)[1],description=$('#eco-description').value.trim();$('#eco-photo-status').textContent='正在壓縮並保留本機照片…';try{const blob=await compress(file,kind==='panorama');if(!isAdmin()||getUser()?.uid!==owner)throw Error('登入已變更，尚未保存');await store('put',{id:crypto.randomUUID(),owner,target,label:target,title,description,kind,blob,createdAt:Date.now(),state:'draft'});$('#eco-photo-status').textContent='已保存本機，請在下方照片佇列預覽後按「上傳公開」。原圖請另行備份。';await renderDrafts()}catch(e){$('#eco-photo-status').textContent=e.message}finally{busy=false;update()}}
 for(const selector of ['#eco-camera','#eco-album'])$(selector).onchange=e=>{const file=e.target.files?.[0];e.target.value='';void capture(file)};update();
 }catch(e){section.textContent=e.message+'，請重新整理後重試。'}
}
